// QuadrantPreviewSidebar.ts
var import_obsidian3 = require("obsidian");
var QUADRANT_PREVIEW_VIEW_TYPE = "magma-quadrant-preview-sidebar";
var QuadrantPreviewSidebar = class extends import_obsidian3.ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.currentFile = null;
    this.lastContent = "";
    this.quadrantData = {
      1: [],
      2: [],
      3: [],
      4: []
    };
    this.plugin = plugin;
  }
  getViewType() {
    return QUADRANT_PREVIEW_VIEW_TYPE;
  }
  getDisplayText() {
    return "\u56DB\u8C61\u9650\u9884\u89C8";
  }
  getIcon() {
    return "calendar-with-checkmark";
  }
  async onOpen() {
    await this.render();
    const activeFile = this.app.workspace.getActiveFile();
    if (activeFile && this.isQuadrantFile(activeFile)) {
      this.updatePreviewForFile(activeFile);
    }
  }
  async onClose() {
  }
  async render() {
    const container = this.containerEl.children[1];
    container.empty();
    container.addClass("magma-preview-container");
    container.style.height = "100%";
    container.style.display = "flex";
    container.style.flexDirection = "column";
    const header = container.createDiv({ cls: "magma-preview-header" });
    header.innerHTML = "<h3>\u56DB\u8C61\u9650\u9884\u89C8</h3>";
    const emptyState = container.createDiv({ cls: "magma-preview-empty" });
    emptyState.innerHTML = "<p>\u6253\u5F00\u56DB\u8C61\u9650\u65F6\u95F4\u7BA1\u7406\u8868\u4EE5\u67E5\u770B\u9884\u89C8</p>";
    const quadrantContainer = container.createDiv({
      cls: "magma-preview-quadrant-container",
      attr: { "style": "flex: 1;" }
    });
    for (let i = 1; i <= 4; i++) {
      this.createQuadrantPreview(quadrantContainer, i);
    }
  }
  createQuadrantPreview(container, quadrantNum) {
    const quadrantNames = {
      1: "\u91CD\u8981\u4E14\u7D27\u6025",
      2: "\u91CD\u8981\u4E0D\u7D27\u6025",
      3: "\u7D27\u6025\u4E0D\u91CD\u8981",
      4: "\u4E0D\u7D27\u6025\u4E0D\u91CD\u8981"
    };
    const colors = {
      1: "#ff6b6b",
      2: "#4ecdc4",
      3: "#ffe66d",
      4: "#95a5a6"
    };
    const quadrant = container.createDiv({
      cls: `magma-preview-quadrant magma-preview-quadrant-${quadrantNum}`
    });
    const titleEl = quadrant.createDiv({ cls: "magma-preview-quadrant-title" });
    titleEl.innerHTML = `<span style="color: ${colors[quadrantNum]};">\u7B2C${quadrantNum}\u8C61\u9650: ${quadrantNames[quadrantNum]}</span>`;
    const separator = quadrant.createEl("hr", {
      attr: {
        style: `border: none; border-top: 1px solid ${colors[quadrantNum]}; margin: 8px 0;`
      }
    });
    const taskListEl = quadrant.createDiv({ cls: "magma-preview-task-list" });
    taskListEl.dataset.quadrant = quadrantNum.toString();
    const emptyTaskEl = taskListEl.createDiv({ cls: "magma-preview-empty-tasks" });
    emptyTaskEl.innerHTML = "<p>\u8FD8\u6CA1\u6709\u4EFB\u52A1\uFF0C\u53BB\u6DFB\u52A0\u5427</p>";
  }
  isQuadrantFile(file) {
    return file.name.startsWith("\u56DB\u8C61\u9650\u65F6\u95F4\u7BA1\u7406\u8868_") && file.extension === "md";
  }
  // 从外部调用，更新指定文件的预览
  async updatePreviewForFile(file) {
    if (!this.isQuadrantFile(file)) {
      return;
    }
    this.currentFile = file;
    try {
      const content = await this.app.vault.cachedRead(file);
      if (content === this.lastContent)
        return;
      this.lastContent = content;
      this.parseQuadrantContent(content);
      this.renderQuadrantData();
      const container = this.containerEl.querySelector(".magma-preview-quadrant-container");
      const emptyState = this.containerEl.querySelector(".magma-preview-empty");
      if (container)
        container.classList.remove("hidden");
      if (emptyState)
        emptyState.classList.add("hidden");
      const header = this.containerEl.querySelector(".magma-preview-header h3");
      if (header) {
        const dateMatch = file.name.match(/四象限时间管理表_(.+?)\.md/);
        const displayDate = dateMatch ? dateMatch[1] : file.name;
        header.textContent = `\u56DB\u8C61\u9650\u9884\u89C8 - ${displayDate}`;
      }
    } catch (error2) {
      console.error("\u66F4\u65B0\u56DB\u8C61\u9650\u9884\u89C8\u5931\u8D25:", error2);
      new import_obsidian3.Notice("\u66F4\u65B0\u56DB\u8C61\u9650\u9884\u89C8\u5931\u8D25");
    }
  }
  // 解析文件内容，提取四象限数据
  parseQuadrantContent(content) {
    this.quadrantData = {
      1: [],
      2: [],
      3: [],
      4: []
    };
    const quadrantRegex = /^(?:##|###)\s*(?:.*第(一|二|三|四)象限:|(重要且紧急|重要不紧急|紧急不重要|不紧急不重要))/m;
    const quadrantMap = {
      "1": 1,
      "\u4E00": 1,
      "2": 2,
      "\u4E8C": 2,
      "3": 3,
      "\u4E09": 3,
      "4": 4,
      "\u56DB": 4,
      "\u91CD\u8981\u4E14\u7D27\u6025": 1,
      "\u91CD\u8981\u4E0D\u7D27\u6025": 2,
      "\u7D27\u6025\u4E0D\u91CD\u8981": 3,
      "\u4E0D\u7D27\u6025\u4E0D\u91CD\u8981": 4
    };
    const lines = content.split("\n");
    let currentQuadrant = 0;
    for (const line of lines) {
      const match = line.match(quadrantRegex);
      if (match) {
        const quadrantKey = match[1] || match[2];
        currentQuadrant = quadrantMap[quadrantKey] || 0;
        continue;
      }
      if (currentQuadrant > 0 && currentQuadrant <= 4) {
        const listTaskMatch = line.match(/^- \[([ x])\]\s*(?:\*\*)*(.+?)(?:\*\*)*\s*$/);
        if (listTaskMatch) {
          const completed = listTaskMatch[1] === "x";
          const title = listTaskMatch[2].trim();
          this.quadrantData[currentQuadrant].push({
            title,
            completed
          });
          continue;
        }
      }
    }
  }
  // 渲染四象限数据到预览界面
  renderQuadrantData() {
    for (let i = 1; i <= 4; i++) {
      const taskListEl = this.containerEl.querySelector(`.magma-preview-task-list[data-quadrant="${i}"]`);
      if (taskListEl) {
        taskListEl.empty();
        if (this.quadrantData[i].length > 0) {
          this.quadrantData[i].forEach((task) => {
            const taskEl = taskListEl.createDiv({ cls: "magma-preview-task-item" });
            const checkbox = taskEl.createEl("input", {
              type: "checkbox",
              cls: "magma-preview-task-checkbox"
            });
            checkbox.checked = task.completed;
            checkbox.disabled = true;
            const taskText = taskEl.createSpan({ cls: "magma-preview-task-text" });
            taskText.textContent = task.title;
            if (task.completed) {
              taskText.addClass("magma-preview-task-completed");
            }
          });
        } else {
          const emptyTaskEl = taskListEl.createDiv({ cls: "magma-preview-empty-tasks" });
          emptyTaskEl.innerHTML = "<p>\u8FD8\u6CA1\u6709\u4EFB\u52A1\uFF0C\u53BB\u6DFB\u52A0\u5427</p>";
        }
      }
    }
  }
  // 清除预览内容
  clearPreview() {
    this.currentFile = null;
    const container = this.containerEl.querySelector(".magma-preview-quadrant-container");
    const emptyState = this.containerEl.querySelector(".magma-preview-empty");
    if (container)
      container.style.display = "none";
    if (emptyState)
      emptyState.style.display = "block";
    const header = this.containerEl.querySelector(".magma-preview-header h3");
    if (header) {
      header.textContent = "\u56DB\u8C61\u9650\u9884\u89C8";
    }
  }
};

