var RecurringTaskManagerModal = class extends import_obsidian7.Modal {
  constructor(app, plugin) {
    super(app);
    this.items = [];
    this.plugin = plugin;
    this.loadItems();
  }
  loadItems() {
    const raw = this.plugin.settings.recurringTasks || "";
    this.items = [];
    if (!raw.trim())
      return;
    for (const line of raw.split("\n")) {
      const match = line.trim().match(/^([1-4])\|(.+)$/);
      if (match) {
        this.items.push({ quadrant: parseInt(match[1]), text: match[2].trim() });
      }
    }
  }
  async saveItems() {
    this.plugin.settings.recurringTasks = this.items.map((i) => `${i.quadrant}|${i.text}`).join("\n");
    await this.plugin.savePluginSettings();
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("recurring-manager-modal");
    contentEl.createEl("h2", { text: "\u7BA1\u7406\u56FA\u5B9A\u4EFB\u52A1" });
    const qNames = {
      1: "\u7B2C\u4E00\u8C61\u9650\uFF1A\u91CD\u8981\u4E14\u7D27\u6025",
      2: "\u7B2C\u4E8C\u8C61\u9650\uFF1A\u91CD\u8981\u4E0D\u7D27\u6025",
      3: "\u7B2C\u4E09\u8C61\u9650\uFF1A\u7D27\u6025\u4E0D\u91CD\u8981",
      4: "\u7B2C\u56DB\u8C61\u9650\uFF1A\u4E0D\u7D27\u6025\u4E0D\u91CD\u8981"
    };
    const listContainer = contentEl.createEl("div", { cls: "recurring-manager-list" });
    this.renderList(listContainer);
    const addSection = contentEl.createEl("div", { cls: "recurring-manager-add" });
    addSection.createEl("h3", { text: "\u6DFB\u52A0\u56FA\u5B9A\u4EFB\u52A1" });
    const selectRow = addSection.createEl("div", { cls: "recurring-manager-select-row" });
    const quadrantSelect = selectRow.createEl("select", { cls: "recurring-manager-select" });
    for (let i = 1; i <= 4; i++) {
      quadrantSelect.createEl("option", { value: String(i), text: qNames[i] });
    }
    const taskInput = addSection.createEl("input", {
      cls: "recurring-manager-input",
      attr: { type: "text", placeholder: "\u4EFB\u52A1\u5185\u5BB9\uFF08\u5982\uFF1A\u5065\u8EAB\u953B\u70BC\uFF09" }
    });
    const addBtn = addSection.createEl("button", { text: "\u6DFB\u52A0", cls: "recurring-manager-btn" });
    addBtn.addEventListener("click", async () => {
      const quadrant = parseInt(quadrantSelect.value);
      const text = taskInput.value.trim();
      if (!text) {
        new import_obsidian7.Notice("\u8BF7\u586B\u5199\u4EFB\u52A1\u5185\u5BB9");
        return;
      }
      const duplicate = this.items.find((item) => item.quadrant === quadrant && item.text === text);
      if (duplicate) {
        new import_obsidian7.Notice("\u8BE5\u8C61\u9650\u4E0B\u5DF2\u5B58\u5728\u76F8\u540C\u7684\u56FA\u5B9A\u4EFB\u52A1");
        return;
      }
      this.items.push({ quadrant, text });
      await this.saveItems();
      taskInput.value = "";
      this.renderList(listContainer);
    });
    const closeBtn = contentEl.createEl("button", { text: "\u5173\u95ED", cls: "recurring-manager-close" });
    closeBtn.addEventListener("click", () => this.close());
  }
  renderList(container) {
    container.empty();
    if (this.items.length === 0) {
      container.createEl("p", { text: "\u6682\u65E0\u56FA\u5B9A\u4EFB\u52A1\uFF0C\u70B9\u51FB\u4E0B\u65B9\u6DFB\u52A0", cls: "recurring-manager-empty" });
      return;
    }
    const qNames = {
      1: "\u7B2C\u4E00\u8C61\u9650",
      2: "\u7B2C\u4E8C\u8C61\u9650",
      3: "\u7B2C\u4E09\u8C61\u9650",
      4: "\u7B2C\u56DB\u8C61\u9650"
    };
    for (let i = 0; i < this.items.length; i++) {
      const item = this.items[i];
      const row = container.createEl("div", { cls: "recurring-manager-item" });
      row.createEl("span", { cls: "recurring-item-quadrant", text: qNames[item.quadrant] });
      row.createEl("span", { cls: "recurring-item-text", text: item.text });
      const delBtn = row.createEl("button", { text: "\u5220\u9664", cls: "recurring-item-delete" });
      delBtn.addEventListener("click", async () => {
        this.items.splice(i, 1);
        await this.saveItems();
        this.renderList(container);
      });
    }
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};

