      { value: "2", label: "\u7B2C\u4E8C\u8C61\u9650: \u91CD\u8981\u4E0D\u7D27\u6025 \u{1F4C5}" },
      { value: "3", label: "\u7B2C\u4E09\u8C61\u9650: \u7D27\u6025\u4E0D\u91CD\u8981 \u26A1" },
      { value: "4", label: "\u7B2C\u56DB\u8C61\u9650: \u4E0D\u7D27\u6025\u4E0D\u91CD\u8981 \u{1F331}" }
